// Original, gently changing instrumental loop: electric keys, warm bass and soft drums.
export function createMusic(ctx,output){
 const beat=60/86,step=beat/2,chords=[[50,53,57,60],[46,50,53,57],[53,57,60,64],[48,52,55,60]],melody=[0,7,12,7,3,10,7,5,0,7,10,12,7,5,3,7];let next=0,tick=0,running=false;
 function note(midi,time,duration,volume,type='sine'){const oscillator=ctx.createOscillator(),envelope=ctx.createGain();oscillator.type=type;oscillator.frequency.value=440*2**((midi-69)/12);envelope.gain.setValueAtTime(0,time);envelope.gain.linearRampToValueAtTime(volume,time+.025);envelope.gain.exponentialRampToValueAtTime(.0001,time+duration);oscillator.connect(envelope);envelope.connect(output);oscillator.start(time);oscillator.stop(time+duration+.03);oscillator.onended=()=>{oscillator.disconnect();envelope.disconnect()}}
 function kick(time){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(105,time);o.frequency.exponentialRampToValueAtTime(43,time+.16);g.gain.setValueAtTime(.12,time);g.gain.exponentialRampToValueAtTime(.0001,time+.22);o.connect(g);g.connect(output);o.start(time);o.stop(time+.24);o.onended=()=>{o.disconnect();g.disconnect()}}
 return{update(enabled){if(!enabled){running=false;return}if(!running||next<ctx.currentTime-.2){next=ctx.currentTime+.04;running=true}while(next<ctx.currentTime+.16){const bar=Math.floor(tick/8),index=tick%8,chord=chords[Math.floor(bar/2)%4];if(index===0){for(const midi of chord)note(midi+12,next,beat*4.2,.045,'triangle');note(chord[0]-12,next,beat*1.8,.16)}if(index===4)note(chord[0]-12,next,beat*1.6,.12);if(index===0||index===4)kick(next);if(index%2===0)note(chord[0]+24+melody[Math.floor(tick/2)%melody.length],next,beat*1.2,.045);if(index===2||index===6)note(82,next,.065,.018,'triangle');tick++;next+=step}}};
}
